from paramiko import SSHClient, AutoAddPolicy
from typing import Dict, List
from time import sleep

from taf.rfrl.procedures.resources.python.bts.components.rmod.rmod import Rmod
from taf.rfrl.procedures.resources.python.bts.components.bts_component import BtsComponent
from taf.rfrl.procedures.resources.python.bts.components.component_collection import ComponentCollection
from taf.rfrl.procedures.resources.python.bts.components.cell.cloud_cell import CloudCell
from taf.rfrl.procedures.resources.python.bts.components.antenna.antenna import Antenna
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import log_info, log_debug, pretty_log
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import UnsupportedState, TimeExceeded, ResultError
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import ApiResponse, DuApi, RmodConfig
from taf.rfrl.procedures.resources.python.bts.utils.timer import wait_for


class CloudRmod(Rmod):
    """ Represents RMOD connected to Cloud RAN. """
    def __init__(self,
                 parent: BtsComponent,
                 rmod_info: ApiResponse,
                 api: DuApi,
                 api_alias: str,
                 ssh_ip: str,
                 rmod_init_config: RmodConfig,
                 is_dc: bool):
        """
        :param parent: BTS component to which this RMOD is connected; usually it is DU
        :param rmod_info: information about this RMOD received as a response to API request;
                          must contain following data:
                          {'ant_ports': [{'dist_names': {'config': 'MRBTS-1/EQM-1/APEQM-1/RMOD-1/PHYANT-1',
                                                         'runtime': 'MRBTS-1/EQM_R-1/APEQM_R-1/RMOD_R-1/PHYANT_R-1'},
                                          'id': '1',
                                          'name': 'PHYANT'}],
                           'cell_ids': ['1'],
                           'dist_names': {'config': 'MRBTS-1/EQM-1/APEQM-1/RMOD-1',
                                          'runtime': 'MRBTS-1/EQM_R-1/APEQM_R-1/RMOD_R-1'},
                           'id': '1',
                           'product_code': '475198A.102',
                           'serial_number': '6Q182502974'}
        :param api: API used for performing operations on this RMOD
        :param api_alias: name of opened API connection which this RMOD should use
        :param ssh_ip: IP address of this RMOD which will be used to connect via SSH
        :param rmod_init_config: configuration details, taken from init file, of this RMOD
        :param is_dc: True if this RMOD is connected to DU using Direct Connectivity, False if using Fronthaul Gateway
        """
        log_info('Creating new Cloud RMOD')
        super(CloudRmod, self).__init__(rmod_info['dist_names']['config'].split('/')[-1],
                                        api,
                                        api_alias,
                                        ssh_ip,
                                        rmod_init_config)
        self._parent = parent
        self._id = rmod_info['id']
        self._serial_number = rmod_info['serial_number']
        self._product_code = rmod_info['product_code']
        self._config_dist_name = rmod_info['dist_names']['config']
        self._runtime_dist_name = rmod_info['dist_names']['runtime']
        self._ssh = SSHClient()
        self._ssh_shell = None
        self._rmod_info = rmod_info
        self._rmod_config_info = self._parent.config.get_many(dist_names=[self._runtime_dist_name],
                                                              log_to_console=False)
        self._link_protocol = self._rmod_config_info[self._runtime_dist_name]['l3Protocol'].lower().split('_')[0]
        self._is_dc = is_dc
        log_debug(f'Cloud RMOD details:\n'
                  f'name={self._name}\n'
                  f'id={self._id}\n'
                  f'serial_number={self._serial_number}\n'
                  f'product_code={self._product_code}\n'
                  f'link_protocol={self._link_protocol}\n'
                  f'ssh_ip={self._ssh_ip}\n'
                  f'config_dist_name={self._config_dist_name}\n'
                  f'runtime_dist_name={self._runtime_dist_name}\n'
                  f'is_dc={self._is_dc}\n')

    @property
    def du(self) -> BtsComponent:
        """ Returns DU to which this RMOD is connected. """
        return self._parent

    @property
    def config_dist_name(self) -> str:
        """ Returns configuration dist name of this RMOD. """
        return self._config_dist_name

    @property
    def runtime_dist_name(self) -> str:
        """ Returns runtime dist name of this RMOD. """
        return self._runtime_dist_name

    @property
    def link_protocol(self) -> str:
        """ Returns link protocol of this RMOD, i.e. 'cpri'. """
        return self._link_protocol

    @property
    def is_dc(self) -> bool:
        """ Returns True if this RMOD is connected to DU using Direct Connectivity, False if using Fronthaul Gateway. """
        return self._is_dc

    @pretty_log
    def load(self):
        """
        Loads all components currently connected to this RMOD.
        Each time current RMOD configuration changes (i.e. due to recomissioning which adds/removes BTS component)
        RMOD needs to be reloaded using this method.
        """
        log_info(f'Loading {self._name}', to_console=True)
        cells_info = self._api.get_vdu_cells_status(vdu_connection=self._api_alias)
        rmod_cell_ids = self._rmod_info['cell_ids'] if self._rmod_info['cell_ids'] is not None else []

        self._cells = ComponentCollection(
            [CloudCell(parent=self,
                       cell_info=cell_info,
                       api=self._api,
                       api_alias=self._api_alias)
             for cell_info in cells_info if cell_info['id'] in rmod_cell_ids])

        self._antennas = ComponentCollection(
            [Antenna(parent=self,
                     antenna_info=antenna_info)
             for antenna_info in self._rmod_info['ant_ports']])

    @pretty_log
    def lock(self, timeout: int = 60):
        """
        Locks this RMOD by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be successfully completed;
                        if 0 provided then there will be no waiting for operation to complete;
                        defaults to 60
        """
        log_info(f'Locking {self._name} with {timeout}s timeout', to_console=True)
        api_response = self._api.lock_rmods(rmod_id_list=[self._get_id_from_config_dist_name()],
                                            timeout=5,
                                            vdu_connection=self._api_alias)

        if timeout:
            wait_for(expected_value='success',
                     abort_if='failure',
                     timeout=timeout,
                     callback=self._get_status_of_lock,
                     operation_id=api_response['id'])

    @pretty_log
    def unlock(self, timeout: int = 60):
        """
        Unlocks this RMOD by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be successfully completed;
                        if 0 provided then there will be no waiting for operation to complete;
                        defaults to 60
        """
        log_info(f'Unlocking {self._name} with {timeout}s timeout', to_console=True)
        api_response = self._api.unlock_rmods(rmod_id_list=[self._get_id_from_config_dist_name()],
                                              timeout=5,
                                              vdu_connection=self._api_alias)

        if timeout:
            wait_for(expected_value='success',
                     abort_if='failure',
                     timeout=timeout,
                     callback=self._get_status_of_unlock,
                     operation_id=api_response['id'])

    @pretty_log
    def reset(self, timeout: int = 0):
        """
        Resets this RMOD by sending appropriate API command.
        :param timeout: time (in seconds) in which operation should be successfully completed;
                        if 0 provided then there will be no waiting for operation to complete;
                        defaults to 0
        """
        log_info(f'Resetting {self._name} with {timeout}s timeout', to_console=True)
        api_response = self._api.reset_rmods(rmods_list=[self._id],
                                             timeout=5,
                                             vdu_connection=self._api_alias)

        if timeout:
            wait_for(expected_value='success',
                     abort_if='failure',
                     timeout=timeout,
                     callback=self._get_status_of_reset,
                     operation_id=api_response['operation_id'])

    @pretty_log
    def get_power_usage(self) -> float:
        """
        Returns current power usage (in watts) of this RMOD.
        :return: current power usage (in watts) of this RMOD
        :raises ResultError: if any step of reading power usage from this RMOD fails
        """
        log_info(f'Getting power usage of {self._name}', to_console=True)
        frmon_output = self._get_frmon_psu_measurements_output_via_ssh()
        power_usage = self._get_power_usage_from_frmon_output(frmon_output)
        log_info(f'Power usage of {self._name}: {power_usage}W', to_console=True)
        return power_usage

    @pretty_log
    def enable_fail_safe_mode(self):
        """
        Enables fail-safe mode on this RMOD.
        :raises ResultError: if any step of enabling fail-safe mode on this RMOD fails
        """
        log_info(f'Enabling fail-safe mode on {self._name}', to_console=True)
        try:
            self._connect_via_ssh()
            self._start_frmon_shell()
            self._start_frmon_reset_control()
            output = self._execute_and_return_output_via_ssh('/CI/ResetControl/module action enable_fail_safe_mode')

            if 'done ok' not in output:
                raise ResultError(f'Cannot enable fail-safe mode via FRMON, incorrect SSH output: {output}')
        finally:
            self._disconnect_via_ssh()

    @pretty_log
    def disable_fail_safe_mode(self):
        """
        Disables fail-safe mode on this RMOD.
        :raises ResultError: if any step of disabling fail-safe mode on this RMOD fails
        """
        log_info(f'Disabling fail-safe mode on {self._name}', to_console=True)
        try:
            self._connect_via_ssh()
            self._start_frmon_shell()
            self._start_frmon_reset_control()
            output = self._execute_and_return_output_via_ssh('/CI/ResetControl/module action disable_fail_safe_mode')

            if 'done ok' not in output:
                raise ResultError(f'Cannot disable fail-safe mode via FRMON, incorrect SSH output: {output}')
        finally:
            self._disconnect_via_ssh()

    @pretty_log
    def is_in_fail_safe_mode(self) -> bool:
        """
        Checks whether this RMOD is currently in fail-safe mode.
        :return: True if this RMOD is in fail-safe mode, False otherwise
        :raises ResultError: if any step of checking fail-safe mode on this RMOD fails
        """
        log_info(f'Checking whether {self._name} is in fail-safe mode', to_console=True)

        try:
            self._connect_via_ssh()
            self._start_frmon_shell()
            self._start_frmon_reset_control()
            output = self._execute_and_return_output_via_ssh('/CI/ResetControl/module get fail_safe_mode')

            if any([fail_safe_mode_activation_phrase in output for fail_safe_mode_activation_phrase in [' ENABLED', ' ACTIVE']]):
                log_info(f'{self._name} is in fail-safe mode', to_console=True)
                return True
            else:
                log_info(f'{self._name} is not in fail-safe mode', to_console=True)
                return False
        finally:
            self._disconnect_via_ssh()

    @pretty_log
    def is_mmimo(self) -> bool:
        """
        Checks whether this RMOD is a massive MIMO RMOD.
        :return: True if this RMOD is a massive MIMO RMOD, False otherwise
        """
        return any('phyant' in antenna.name.lower() for antenna in self._antennas)

    @pretty_log
    def download_file(self, file_path: str, local_dir_path: str) -> str:
        """
        Downloads file from this RMOD to local machine.
        :param file_path: absolute path to file on this RMOD which should be downloaded, i.e. '/mnt/runtime/snapshot.zip'
        :param local_dir_path: absolute path to directory on local machine where file should be downloaded, i.e. '/home/ute/Downloads'
        :return: absolute path to downloaded file on local machine, i.e. '/home/ute/Downloads/snapshot.zip'
        :raises ResultError: if any step of downloading file from this RMOD fails
        """
        self._copy_file_to_parent(file_path)
        return self._move_file_from_parent_to_local_machine(file_path, local_dir_path)

    @pretty_log
    def remove_file(self, file_path: str):
        """
        Removes file from this RMOD. Won't fail if file does not exist.
        :param file_path: absolute path to file on this RMOD which should be removed, i.e. '/mnt/runtime/snapshot.zip'
        """
        log_info(f'Removing file {file_path} from {self._name}', to_console=True)
        try:
            self._connect_via_ssh()
            self._execute_via_ssh(f'rm -f {file_path}')
        finally:
            self._disconnect_via_ssh()

    def _get_id_from_config_dist_name(self) -> str:
        return self._config_dist_name.rsplit('-', 1)[-1]

    def _get_expected_statuses(self, state: str) -> Dict[str, str]:
        expected_statuses = {'online': {'procedural_status': 'configured',
                                        'operational_state': 'enabled',
                                        'availability_status': 'on line',
                                        'administrative_state': 'Unlocked'},
                             'locked': {'procedural_status': 'configured',
                                        'operational_state': 'enabled',
                                        'availability_status': 'on line',
                                        'administrative_state': 'Locked'},
                             'failed': {'procedural_status': None,
                                        'operational_state': 'disabled',
                                        'availability_status': 'failed',
                                        'administrative_state': 'Unlocked'},
                             'not_installed': {'procedural_status': 'not initialized',
                                               'operational_state': 'disabled',
                                               'availability_status': 'not installed',
                                               'administrative_state': 'Unlocked'}}

        if state not in expected_statuses:
            raise UnsupportedState(self._UNSUPPORTED_STATE_ERROR_MSG.format(state, self._name))

        return expected_statuses[state]

    def _get_current_statuses(self, statuses_names: List[str]) -> Dict[str, str]:
        current_statuses = {}
        rmods_info = self._api.get_rmods_status(vdu_connection=self._api_alias)

        for rmod_info in rmods_info:
            if rmod_info['dist_names']['config'] == self._config_dist_name:
                for status_name in statuses_names:
                    current_status_value = rmod_info.get(status_name)
                    current_statuses[status_name] = current_status_value

        return current_statuses

    def _get_status_of_lock(self, operation_id: str) -> str:
        api_response = self._api.get_operation_state_of_locking_rmods(operation_id=operation_id,
                                                                      vdu_connection=self._api_alias)
        return api_response['status']

    def _get_status_of_unlock(self, operation_id: str) -> str:
        api_response = self._api.get_operation_of_unlocking_rmods(operation_id=operation_id,
                                                                  vdu_connection=self._api_alias)
        return api_response['status']

    def _get_status_of_reset(self, operation_id: str) -> str:
        api_response = self._api.get_reset_rmods_operation_status(operation_id=operation_id,
                                                                  vdu_connection=self._api_alias)
        return api_response['status']

    def _start_frmon_shell(self):
        self._execute_and_await_output_via_ssh('frmonShellClient 127.0.0.1 2000', expected_output='$')

    def _get_frmon_psu_measurements_output_via_ssh(self) -> str:
        try:
            self._connect_via_ssh()
            self._start_frmon_shell()
            output = self._execute_and_return_output_via_ssh('/ action create PsuMeasurements /psu /module')

            if 'error 0x08 "Invalid <device_path>' in output:
                output = self._execute_and_return_output_via_ssh('/ action create PsuMeasurements /psu /rf/psu')

            if not ('done ok' in output or 'Path already taken' in output):
                raise ResultError(f'Cannot start FRMON measurements, incorrect SSH output: {output}')

            output = self._execute_and_return_output_via_ssh('/psu action measure')
            self._execute_and_await_output_via_ssh('/psu action terminate',
                                                   expected_output='done ok')
            return output
        finally:
            self._disconnect_via_ssh()

    def _connect_via_ssh(self):
        self._connect_to_parent_via_ssh()

        log_debug(f'Connecting to {self._name} via SSH using IP address {self._ssh_ip}')
        namespace = '' if self._parent.sw.version.stream >= self._parent.sw.STREAM_26R1 else '-cran1'
        self._execute_and_await_output_via_ssh(f'oc exec -it po{namespace}-oamfh-0 -c ctr{namespace}-oamfh bash -n cran1',
                                               expected_output='bash')
        proxy = ' -b 70.70.70.1' if self._is_dc else ''
        self._execute_and_await_output_via_ssh(f'ssh{proxy} {self._rmod_init_config.default_ssh_connection_details.username}@{self._ssh_ip}',
                                               expected_output='Are you sure you want to continue connecting')
        self._execute_and_await_output_via_ssh('yes',
                                               expected_output='password:')
        self._execute_and_await_output_via_ssh(f'{self._rmod_init_config.default_ssh_connection_details.password}',
                                               expected_output='Last login:')

    def _connect_to_parent_via_ssh(self):
        log_debug(f'Connecting to {self._parent.name} via SSH using IP address {self._parent.ssh_details.addr}')
        self._ssh.load_system_host_keys()
        self._ssh.set_missing_host_key_policy(AutoAddPolicy())
        self._ssh.connect(hostname=self._parent.ssh_details.addr,
                          username=self._parent.ssh_details.username,
                          password=self._parent.ssh_details.password)
        self._ssh_shell = self._ssh.invoke_shell()

    def _execute_and_await_output_via_ssh(self, cmd: str, expected_output: str):
        self._execute_via_ssh(cmd)

        log_debug(f'Awaiting output from {self._name} via SSH: {expected_output}')
        wait_for(expected_value=True,
                 abort_if=None,
                 timeout=20,
                 callback=self._is_ssh_output_as_expected,
                 expected_output=expected_output)

    def _execute_and_return_output_via_ssh(self, cmd: str) -> str:
        self._execute_via_ssh(cmd)
        return self._read_output_via_ssh()

    def _execute_via_ssh(self, cmd: str):
        log_debug(f'Executing on {self._name} via SSH: {cmd}')
        wait_for(expected_value=True,
                 abort_if=None,
                 timeout=5,
                 callback=self._ssh_shell.send_ready)
        self._ssh_shell.send(f'{cmd}\r')

    def _is_ssh_output_as_expected(self, expected_output: str) -> bool:
        try:
            return expected_output in self._read_output_via_ssh()
        except TimeExceeded:
            return False

    def _read_output_via_ssh(self) -> str:
        log_debug(f'Reading output from {self._name} via SSH')
        wait_for(expected_value=True,
                 abort_if=None,
                 timeout=5,
                 callback=self._ssh_shell.recv_ready)
        sleep(1)
        output = self._ssh_shell.recv(9999).decode('utf-8')
        log_debug(f'{self._name} SSH output: \n{output}')
        return output

    def _disconnect_via_ssh(self):
        log_debug(f'Disconnecting from {self._name} via SSH')
        self._ssh.close()
        self._ssh_shell = None

    def _get_power_usage_from_frmon_output(self, frmon_output: str) -> float:
        for line in frmon_output.split('\n'):
            if line.startswith('ret'):
                return float(line.split(' ')[-1])

        raise ResultError(f'Cannot read {self._name} power usage from FRMON output: {frmon_output}')

    def _start_frmon_reset_control(self):
        output = self._execute_and_return_output_via_ssh('/ action create ResetControl /CI/ResetControl/module /module')

        if not ('done ok' in output or 'Path already taken' in output):
            raise ResultError(f'Cannot start FRMON reset control, incorrect SSH output: {output}')

    def _copy_file_to_parent(self, file_path: str):
        file_name = file_path.split('/')[-1]
        namespace = '' if self._parent.sw.version.stream >= self._parent.sw.STREAM_26R1 else '-cran1'

        try:
            log_info(f'Downloading file {file_path} from {self._name} to /tmp on {self._parent.name}', to_console=True)
            self._connect_to_parent_via_ssh()
            self._copy_file_from_rmod_to_fhnet(file_path, namespace)
            self._copy_file_from_fhnet_to_parent(file_name, namespace)
            self._remove_file_from_fhnet(file_name, namespace)
        finally:
            self._disconnect_via_ssh()

    def _copy_file_from_rmod_to_fhnet(self, file_path: str, namespace: str):
        rmod_user_name = self._rmod_init_config.default_ssh_connection_details.username
        proxy = ' -o BindAddress=70.70.70.1' if self._is_dc else ''
        self._execute_and_await_output_via_ssh(cmd=f'oc exec -it po{namespace}-oamfh-0 -c ctr{namespace}-oamfh -n cran1 -- '
                                                   f'scp{proxy} {rmod_user_name}@{self._ssh_ip}:{file_path} /tmp',
                                               expected_output='Are you sure you want to continue connecting')
        self._execute_and_await_output_via_ssh(cmd='yes',
                                               expected_output='password:')
        self._execute_and_await_output_via_ssh(cmd=f'{self._rmod_init_config.default_ssh_connection_details.password}',
                                               expected_output='100%')

    def _copy_file_from_fhnet_to_parent(self, file_name: str, namespace: str):
        self._execute_and_await_output_via_ssh(cmd=f'oc exec -it po{namespace}-oamfh-0 -c ctr{namespace}-oamfh -n cran1 '
                                                   f'scp /tmp/{file_name} {self._parent.ssh_details.username}@{self._parent.ssh_details.addr}:/tmp',
                                               expected_output='Are you sure you want to continue connecting')
        self._execute_and_await_output_via_ssh(cmd='yes',
                                               expected_output='password:')
        self._execute_and_await_output_via_ssh(cmd=f'{self._parent.ssh_details.password}',
                                               expected_output='100%')

    def _remove_file_from_fhnet(self, file_name: str, namespace: str):
        self._execute_and_await_output_via_ssh(cmd=f'oc exec -it po{namespace}-oamfh-0 -c ctr{namespace}-oamfh -n cran1 rm /tmp/{file_name}',
                                               expected_output='$')

    def _move_file_from_parent_to_local_machine(self, file_path: str, local_dir_path: str) -> str:
        file_name = file_path.split('/')[-1]
        downloaded_file_path = self._parent.download_file(file_path=f'/tmp/{file_name}', local_dir_path=local_dir_path)
        self._parent.remove_file(file_path=f'/tmp/{file_name}')
        return downloaded_file_path
